     1	import { NextRequest, NextResponse } from "next/server";
     2	import { db } from "@/lib/db";
     3	import { currentUser } from "@/lib/auth";
     4	import { vmRrd, nodeRrd, pveFor } from "@/lib/proxmox";
     5	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
     6	
     7	export const dynamic = "force-dynamic";
     8	
     9	export async function GET(req: NextRequest) {
    10	  const user = await currentUser();
    11	  if (!user) {
    12	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
    13	  }
    14	
    15	  const timeframe = ["hour", "day", "week", "month"].includes(req.nextUrl.searchParams.get("tf") ?? "")
    16	    ? req.nextUrl.searchParams.get("tf")!
    17	    : "hour";
    18	
    19	  const serverId = req.nextUrl.searchParams.get("serverId");
    20	  try {
    21	    if (serverId) {
    22	      const server = await db.server.findUnique({ where: { id: serverId }, include: { node: true } });
    23	      if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
    24	        return NextResponse.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
    25	      }
    26	      // Query the node the VM actually lives on — vmids collide across nodes, so
    27	      // defaulting to the primary would leak another tenant's same-numbered VM.
    28	      const conn = server.node
    29	        ? pveFor({
    30	            apiUrl: server.node.apiUrl,
    31	            pveNode: server.node.pveNode,
    32	            tokenId: server.node.tokenId,
    33	            tokenSecret: server.node.tokenSecret,
    34	          })
    35	        : undefined;
    36	      const data = await vmRrd(server.vmid, timeframe, conn);
    37	      return NextResponse.json({ data }, { headers: NO_STORE_HEADERS });
    38	    }
    39	    if (user.role !== "ADMIN") {
    40	      return NextResponse.json({ error: "forbidden" }, { status: 403, headers: NO_STORE_HEADERS });
    41	    }
    42	    const data = await nodeRrd(timeframe);
    43	    return NextResponse.json({ data }, { headers: NO_STORE_HEADERS });
    44	  } catch {
    45	    // An empty series is the SAME shape we return for a VM that genuinely has
    46	    // no RRD data yet, so swallowing the error here told the customer "your
    47	    // server reported nothing" when the truth was "we could not reach Proxmox
    48	    // to ask". Keep the 200 + empty array (the chart handles it), but state
    49	    // plainly that this is an unavailable upstream, not an observed silence.
    50	    return NextResponse.json(
    51	      { data: [], unavailable: true },
    52	      { headers: NO_STORE_HEADERS },
    53	    );
    54	  }
    55	}

1	import { db } from "./db";
2	import { pve, node as primaryNode, pveFor } from "./proxmox";
3	import type { Node } from "@prisma/client";
4	import { COMPONENT_LABELS, SEVERITY_LABEL, type HealthComponentKey } from "./status-copy";
5	import { alertIncidentOpened, alertIncidentResolved } from "./discord-status-alerts";
6	
7	/**
8	 * Shared, READ-ONLY monitoring helpers for Nxeon.
9	 *
10	 * Everything here is safe to call from server components (status page, admin
11	 * monitoring) and from the worker sweep (`worker/monitor.ts`). No mutations,
12	 * no secrets in the returned shapes — the public /status page renders off the
13	 * same `getHealth()` logic the API exposes.
14	 *
15	 * Proxmox access is strictly read-only: `GET /nodes/{node}/status` and
16	 * `GET /nodes/{node}/storage/{storage}/status` (+ backup content listing).
17	 */
18	
19	export type CompStatus = "operational" | "degraded" | "down";
20	export type Component = { status: CompStatus; detail: string };
21	
22	export type HealthReport = {
23	  web: Component;
24	  db: Component;
25	  worker: Component;
26	  proxmox: Component;
27	  checkedAt: string;
28	};
29	
30	// ---- Thresholds (env-overridable) ---------------------------------------
31	
32	/** Worker is expected to touch the queue within this window; older QUEUED work ⇒ down. */
33	export const WORKER_STALE_MS = Number(process.env.NXEON_WORKER_STALE_MS ?? 2 * 60_000);
34	/** A Job sitting in RUNNING longer than this is considered stuck. */
35	export const STUCK_JOB_MS = Number(process.env.NXEON_STUCK_JOB_MS ?? 15 * 60_000);
36	/** Storage usage above this fraction trips a disk-capacity alert. */
37	export const DISK_WARN_RATIO = Number(process.env.NXEON_DISK_WARN_RATIO ?? 0.85);
38	/** Node RAM usage above this fraction trips an alert. */
39	export const RAM_WARN_RATIO = Number(process.env.NXEON_RAM_WARN_RATIO ?? 0.9);
40	/** No fresh backup within this window ⇒ backups look stale. */
41	export const BACKUP_STALE_MS = Number(process.env.NXEON_BACKUP_STALE_MS ?? 48 * 60 * 60_000);
42	/** QUEUED backlog at/above this depth trips an alert. */
43	export const QUEUE_BACKLOG_ALERT = Number(process.env.NXEON_QUEUE_BACKLOG_ALERT ?? 25);
44	
45	// ---- Small formatters ----------------------------------------------------
46	
47	/** Compact human age from a millisecond duration. */
48	export function fmtAge(ms: number): string {
49	  if (ms < 0) ms = 0;
50	  const m = Math.floor(ms / 60_000);
51	  if (m < 1) return "just now";
52	  if (m < 60) return `${m}m`;
53	  const h = Math.floor(m / 60);
54	  if (h < 24) return `${h}h`;
55	  const d = Math.floor(h / 24);
56	  return `${d}d ${h % 24}h`;
57	}
58	
59	// ---- Proxmox targets (read-only) ----------------------------------------
60	
61	type PveTarget = {
62	  label: string;
63	  pveNode: string;
64	  get: (path: string, params?: Record<string, any>) => Promise<any>;
65	  /** Distinct storages worth watching on this node. */
66	  storages: string[];
67	};
68	
69	/**
70	 * Resolve the set of Proxmox nodes to poll. Prefers explicit `Node` rows
71	 * (multi-node), and falls back to the env-configured primary when none exist.
72	 */
73	export async function nodeTargets(): Promise<PveTarget[]> {
74	  const nodes = await db.node.findMany({
75	    where: { enabled: true },
76	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
77	  });
78	  if (nodes.length === 0) {
79	    return [
80	      {
81	        label: primaryNode || "primary",
82	        pveNode: primaryNode,
83	        get: (p, pp) => pve.get(p, pp),
84	        storages: ["vmdata", "backup"],
85	      },
86	    ];
87	  }
88	  return nodes.map((n: Node) => {
89	    const client = pveFor({
90	      apiUrl: n.apiUrl,
91	      pveNode: n.pveNode,
92	      tokenId: n.tokenId,
93	      tokenSecret: n.tokenSecret,
94	    });
95	    const storages = [n.storageNvme, n.storageHdd, "backup"].filter(
96	      (v, i, a) => v && a.indexOf(v) === i
97	    );
98	    return { label: n.name, pveNode: n.pveNode, get: client.get, storages };
99	  });
100	}
101	
102	export type StorageUsage = {
103	  node: string;
104	  storage: string;
105	  total: number;
106	  used: number;
107	  avail: number;
108	  ratio: number;
109	  reachable: boolean;
110	};
111	
112	/** Per-node, per-storage disk usage (bytes). Unreachable storages are marked. */
113	export async function nodeStorageUsage(): Promise<StorageUsage[]> {
114	  const targets = await nodeTargets();
115	  const out: StorageUsage[] = [];
116	  for (const t of targets) {
117	    for (const storage of t.storages) {
118	      try {
119	        const st = await t.get(`/nodes/${t.pveNode}/storage/${storage}/status`);
120	        const total = Number(st?.total ?? 0);
121	        const used = Number(st?.used ?? 0);
122	        const avail = Number(st?.avail ?? Math.max(0, total - used));
123	        out.push({
124	          node: t.label,
125	          storage,
126	          total,
127	          used,
128	          avail,
129	          ratio: total > 0 ? used / total : 0,
130	          reachable: true,
131	        });
132	      } catch {
133	        out.push({ node: t.label, storage, total: 0, used: 0, avail: 0, ratio: 0, reachable: false });
134	      }
135	    }
136	  }
137	  return out;
138	}
139	
140	export type NodeRam = {
141	  node: string;
142	  total: number;
143	  used: number;
144	  ratio: number;
145	  cpu: number;
146	  /** Physical CPU thread count reported by the node (cpuinfo.cpus). 0 if unknown. */
147	  cores: number;
148	  reachable: boolean;
149	};
150	
151	/** Per-node RAM + CPU load from the node status endpoint. */
152	export async function nodeRamUsage(): Promise<NodeRam[]> {
153	  const targets = await nodeTargets();
154	  return Promise.all(
155	    targets.map(async (t) => {
156	      try {
157	        const s = await t.get(`/nodes/${t.pveNode}/status`);
158	        const total = Number(s?.memory?.total ?? 0);
159	        const used = Number(s?.memory?.used ?? 0);
160	        return {
161	          node: t.label,
162	          total,
163	          used,
164	          ratio: total > 0 ? used / total : 0,
165	          cpu: Number(s?.cpu ?? 0),
166	          // Proxmox reports the host's thread count under cpuinfo.cpus; used only
167	          // as the denominator for vCPU-overcommit context in lib/node-capacity.
168	          cores: Number(s?.cpuinfo?.cpus ?? 0),
169	          reachable: true,
170	        };
171	      } catch {
172	        return { node: t.label, total: 0, used: 0, ratio: 0, cpu: 0, cores: 0, reachable: false };
173	      }
174	    })
175	  );
176	}
177	
178	export type BackupSummary = {
179	  count: number;
180	  /** Unix seconds of the most recent backup (freshness signal). */
181	  newestCtime: number | null;
182	  /** Unix seconds of the oldest backup on disk. */
183	  oldestCtime: number | null;
184	  reachable: boolean;
185	};
186	
187	/**
188	 * Summarise backups across all nodes' `backup` storage. Best-effort: if the
189	 * storage/content endpoint isn't available the node is simply skipped.
190	 */
191	export async function backupSummary(): Promise<BackupSummary> {
192	  const targets = await nodeTargets();
193	  let count = 0;
194	  let newest: number | null = null;
195	  let oldest: number | null = null;
196	  let reachable = false;
197	  for (const t of targets) {
198	    try {
199	      const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/backup/content`, {
200	        content: "backup",
201	      });
202	      reachable = true;
203	      for (const b of items ?? []) {
204	        const ct = Number(b?.ctime ?? 0);
205	        if (!ct) continue;
206	        count++;
207	        if (newest === null || ct > newest) newest = ct;
208	        if (oldest === null || ct < oldest) oldest = ct;
209	      }
210	    } catch {
211	      // storage/content not available on this node — skip
212	    }
213	  }
214	  return { count, newestCtime: newest, oldestCtime: oldest, reachable };
215	}
216	
217	// ---- Worker / job health -------------------------------------------------
218	
219	export type StuckJob = {
220	  id: string;
221	  type: string;
222	  updatedAt: Date;
223	  attempts: number;
224	  serverId: string | null;
225	  hostname: string | null;
226	};
227	
228	/** Jobs stuck in RUNNING past the stuck threshold. */
229	export async function stuckJobs(): Promise<StuckJob[]> {
230	  const rows = await db.job.findMany({
231	    where: { status: "RUNNING", updatedAt: { lt: new Date(Date.now() - STUCK_JOB_MS) } },
232	    orderBy: { updatedAt: "asc" },
233	    take: 20,
234	    select: {
235	      id: true,
236	      type: true,
237	      updatedAt: true,
238	      attempts: true,
239	      serverId: true,
240	      server: { select: { hostname: true } },
241	    },
242	  });
243	  return rows.map((r) => ({
244	    id: r.id,
245	    type: r.type,
246	    updatedAt: r.updatedAt,
247	    attempts: r.attempts,
248	    serverId: r.serverId,
249	    hostname: r.server?.hostname ?? null,
250	  }));
251	}
252	
253	export type WorkerHealth = {
254	  status: CompStatus;
255	  detail: string;
256	  newestUpdatedAt: Date | null;
257	  stuckRunning: number;
258	  queuedBacklog: number;
259	  staleQueued: number;
260	};
261	
262	/**
263	 * Worker liveness inferred from the Job queue:
264	 *  - QUEUED work older than WORKER_STALE_MS that hasn't been picked up ⇒ down
265	 *    (the loop isn't draining the queue).
266	 *  - Jobs stuck RUNNING past STUCK_JOB_MS ⇒ degraded.
267	 *  - Otherwise operational (an empty/fresh queue is healthy, even if idle).
268	 */
269	export async function workerHealth(): Promise<WorkerHealth> {
270	  const now = Date.now();
271	  const [newest, stuckRunning, queuedBacklog, staleQueued] = await Promise.all([
272	    db.job.findFirst({ orderBy: { updatedAt: "desc" }, select: { updatedAt: true } }),
273	    db.job.count({ where: { status: "RUNNING", updatedAt: { lt: new Date(now - STUCK_JOB_MS) } } }),
274	    db.job.count({ where: { status: "QUEUED" } }),
275	    db.job.count({ where: { status: "QUEUED", createdAt: { lt: new Date(now - WORKER_STALE_MS) } } }),
276	  ]);
277	
278	  let status: CompStatus = "operational";
279	  let detail = newest
280	    ? `last job update ${fmtAge(now - newest.updatedAt.getTime())} ago`
281	    : "idle — no jobs processed yet";
282	
283	  if (staleQueued > 0) {
284	    status = "down";
285	    detail = `${staleQueued} job(s) queued but not picked up — worker may be stopped`;
286	  } else if (stuckRunning > 0) {
287	    status = "degraded";
288	    detail = `${stuckRunning} job(s) stuck running > ${Math.round(STUCK_JOB_MS / 60_000)}m`;
289	  }
290	
291	  return {
292	    status,
293	    detail,
294	    newestUpdatedAt: newest?.updatedAt ?? null,
295	    stuckRunning,
296	    queuedBacklog,
297	    staleQueued,
298	  };
299	}
300	
301	// ---- Component health (db / proxmox) ------------------------------------
302	
303	async function dbHealth(): Promise<Component> {
304	  try {
305	    await db.$queryRaw`SELECT 1`;
306	    return { status: "operational", detail: "responding" };
307	  } catch (e: any) {
308	    return { status: "down", detail: String(e?.message ?? e).slice(0, 120) };
309	  }
310	}
311	
312	async function proxmoxHealth(): Promise<Component> {
313	  const targets = await nodeTargets();
314	  let ok = 0;
315	  let fail = 0;
316	  for (const t of targets) {
317	    try {
318	      await t.get(`/nodes/${t.pveNode}/status`);
319	      ok++;
320	    } catch {
321	      fail++;
322	    }
323	  }
324	  if (ok === 0) return { status: "down", detail: "no Proxmox node reachable" };
325	  if (fail > 0) return { status: "degraded", detail: `${fail} of ${ok + fail} nodes unreachable` };
326	  return { status: "operational", detail: `${ok} node(s) reachable` };
327	}
328	
329	/** Full health report — the source of truth for /api/health and /status. */
330	export async function getHealth(): Promise<HealthReport> {
331	  const [dbc, wh, px] = await Promise.all([dbHealth(), workerHealth(), proxmoxHealth()]);
332	  return {
333	    web: { status: "operational", detail: "serving requests" },
334	    db: dbc,
335	    worker: { status: wh.status, detail: wh.detail },
336	    proxmox: px,
337	    checkedAt: new Date().toISOString(),
338	  };
339	}
340	
341	/** Roll the four components up into a single worst-of status. */
342	export function overallStatus(h: HealthReport): CompStatus {
343	  return worstStatus([h.web.status, h.db.status, h.worker.status, h.proxmox.status]);
344	}
345	
346	// ===========================================================================
347	// History layer: HealthSample snapshots, uptime math, and StatusIncident state
348	//
349	// The four probes above are INSTANTANEOUS — they say what is true right now and
350	// keep no memory. Everything below turns that into history: the worker monitor
351	// calls sampleHealth() on its cadence to persist one HealthSample per component,
352	// and the readers compute uptime %, a bucketed timeline, and open/resolved
353	// incidents from those rows. All the arithmetic is factored into PURE functions
354	// (uptimeFromSamples / bucketTimeline / decideIncident) so it is unit-testable
355	// with an injected clock and injected samples, no DB required.
356	// ===========================================================================
357	
358	/** The monitored components, as the string keys stored in HealthSample.component. */
359	export const HEALTH_COMPONENTS = ["web", "db", "worker", "proxmox"] as const;
360	export type HealthComponent = HealthComponentKey;
361	
362	export type IncidentSeverity = "degraded" | "down" | "maintenance";
363	
364	/** Consecutive unhealthy samples before an incident auto-opens. */
365	export const INCIDENT_OPEN_STREAK = Number(process.env.NXEON_INCIDENT_OPEN_STREAK ?? 3);
366	/** Consecutive healthy samples before an auto-incident auto-resolves. */
367	export const INCIDENT_RESOLVE_STREAK = Number(process.env.NXEON_INCIDENT_RESOLVE_STREAK ?? 2);
368	/** HealthSample rows older than this are pruned each sweep (keeps the 90-day window backed). */
369	export const HEALTH_SAMPLE_RETENTION_DAYS = Number(process.env.NXEON_HEALTH_RETENTION_DAYS ?? 95);
370	/** Default uptime / timeline window. */
371	export const UPTIME_WINDOW_MS = Number(process.env.NXEON_UPTIME_WINDOW_MS ?? 90 * 24 * 60 * 60_000);
372	
373	/** Worst-of over a set of statuses (down > degraded > operational). */
374	export function worstStatus(statuses: CompStatus[]): CompStatus {
375	  if (statuses.includes("down")) return "down";
376	  if (statuses.includes("degraded")) return "degraded";
377	  return "operational";
378	}
379	
380	// ---- Pure math (no DB, injected clock) ----------------------------------
381	
382	/** Minimal shape the pure readers work on — a status stamped at a time. */
383	export type SampleLite = { status: CompStatus; ts: Date | string | number };
384	
385	function tsMs(t: Date | string | number): number {
386	  return t instanceof Date ? t.getTime() : new Date(t).getTime();
387	}
388	
389	export type UptimeResult = {
390	  /** Fraction operational over the window, 0..100. `null` = no samples yet ("collecting data"). */
391	  pct: number | null;
392	  total: number;
393	  up: number;
394	  degraded: number;
395	  down: number;
396	};
397	
398	/**
399	 * Uptime % from samples in `[now - windowMs, now]`. Only `operational` counts as
400	 * up — degraded/down are both downtime. Returns `pct: null` when the window has
401	 * NO samples, so callers say "collecting data" instead of fabricating 100%.
402	 */
403	export function uptimeFromSamples(samples: SampleLite[], now: number, windowMs: number): UptimeResult {
404	  const cutoff = now - windowMs;
405	  let total = 0;
406	  let up = 0;
407	  let degraded = 0;
408	  let down = 0;
409	  for (const s of samples) {
410	    const t = tsMs(s.ts);
411	    if (t < cutoff || t > now) continue;
412	    total++;
413	    if (s.status === "operational") up++;
414	    else if (s.status === "degraded") degraded++;
415	    else down++;
416	  }
417	  return { pct: total === 0 ? null : (up / total) * 100, total, up, degraded, down };
418	}
419	
420	export type TimelineBucket = {
421	  start: number;
422	  end: number;
423	  /** Worst status observed in the bucket, or `null` when no samples landed in it. */
424	  status: CompStatus | null;
425	  total: number;
426	};
427	
428	/**
429	 * Split the window into `bucketCount` equal buckets and reduce each to its WORST
430	 * status (a single degraded reading in a day colours that day amber). Empty
431	 * buckets stay `null` — the strip renders them as "no data", never as green.
432	 */
433	export function bucketTimeline(
434	  samples: SampleLite[],
435	  now: number,
436	  windowMs: number,
437	  bucketCount: number
438	): TimelineBucket[] {
439	  const n = Math.max(1, Math.floor(bucketCount));
440	  const bucketMs = windowMs / n;
441	  const start0 = now - windowMs;
442	  const buckets: TimelineBucket[] = Array.from({ length: n }, (_, i) => ({
443	    start: start0 + i * bucketMs,
444	    end: start0 + (i + 1) * bucketMs,
445	    status: null,
446	    total: 0,
447	  }));
448	  for (const s of samples) {
449	    const t = tsMs(s.ts);
450	    if (t < start0 || t > now) continue;
451	    let idx = Math.floor((t - start0) / bucketMs);
452	    if (idx < 0) idx = 0;
453	    if (idx >= n) idx = n - 1;
454	    const b = buckets[idx];
455	    b.total++;
456	    b.status = b.status === null ? s.status : worstStatus([b.status, s.status]);
457	  }
458	  return buckets;
459	}
460	
461	export type IncidentDecision =
462	  | { action: "open"; severity: "degraded" | "down" }
463	  | { action: "resolve" }
464	  | { action: "none" };
465	
466	/**
467	 * The auto-incident state machine, pure and deterministic.
468	 *
469	 * `recent` is the most-recent-first run of a component's sample statuses (newest
470	 * at index 0). With no open incident, a leading run of >= INCIDENT_OPEN_STREAK
471	 * unhealthy samples opens one (severity = down if the newest is down, else
472	 * degraded). With one open, a leading run of >= INCIDENT_RESOLVE_STREAK healthy
473	 * samples resolves it. Anything else is a no-op — this is called every sweep, so
474	 * it must be idempotent once the streak condition is (un)met.
475	 */
476	export function decideIncident(recent: CompStatus[], hasOpenIncident: boolean): IncidentDecision {
477	  if (recent.length === 0) return { action: "none" };
478	
479	  let unhealthyStreak = 0;
480	  for (const s of recent) {
481	    if (s !== "operational") unhealthyStreak++;
482	    else break;
483	  }
484	  let healthyStreak = 0;
485	  for (const s of recent) {
486	    if (s === "operational") healthyStreak++;
487	    else break;
488	  }
489	
490	  if (!hasOpenIncident) {
491	    if (unhealthyStreak >= INCIDENT_OPEN_STREAK) {
492	      return { action: "open", severity: recent[0] === "down" ? "down" : "degraded" };
493	    }
494	    return { action: "none" };
495	  }
496	  if (healthyStreak >= INCIDENT_RESOLVE_STREAK) return { action: "resolve" };
497	  return { action: "none" };
498	}
499	
500	/**
501	 * Public-safe copy for an auto-opened incident. Deliberately generic — it names
502	 * the friendly component and the severity, and never embeds the probe's raw
503	 * `detail` (which can carry host:port / upstream error text).
504	 */
505	export function autoIncidentCopy(
506	  component: HealthComponent,
507	  severity: "degraded" | "down"
508	): { title: string; body: string } {
509	  const name = COMPONENT_LABELS[component] ?? component;
510	  const what = severity === "down" ? "a service disruption" : "degraded performance";
511	  return {
512	    title: `${name}: ${SEVERITY_LABEL[severity]}`,
513	    body:
514	      `Our automated monitoring detected ${what} affecting ${name}. Engineers have been ` +
515	      `notified and this incident will update automatically as the component recovers.`,
516	  };
517	}
518	
519	// ---- Snapshot writer (worker cadence) -----------------------------------
520	
521	/**
522	 * Persist one HealthSample per component AND advance the auto-incident state
523	 * machine. Called on the worker monitor cadence (see worker/monitor.ts →
524	 * sampleHealthSweep). Cheap and idempotent: 4-row insert, one small read + at
525	 * most one write per component, plus a bounded retention prune.
526	 */
527	export async function sampleHealth(now: Date = new Date()): Promise<void> {
528	  const report = await getHealth();
529	
530	  await db.healthSample.createMany({
531	    data: HEALTH_COMPONENTS.map((c) => ({
532	      component: c,
533	      status: report[c].status,
534	      detail: report[c].detail ? report[c].detail.slice(0, 240) : null,
535	      ts: now,
536	    })),
537	  });
538	
539	  const lookback = Math.max(INCIDENT_OPEN_STREAK, INCIDENT_RESOLVE_STREAK, 1);
540	  for (const c of HEALTH_COMPONENTS) {
541	    const recentRows = await db.healthSample.findMany({
542	      where: { component: c },
543	      orderBy: { ts: "desc" },
544	      take: lookback,
545	      select: { status: true },
546	    });
547	    const recent = recentRows.map((r) => r.status as CompStatus);
548	    const open = await db.statusIncident.findFirst({
549	      where: { component: c, resolvedAt: null, auto: true },
550	      orderBy: { startedAt: "desc" },
551	    });
552	    const decision = decideIncident(recent, !!open);
553	    if (decision.action === "open" && !open) {
554	      const copy = autoIncidentCopy(c, decision.severity);
555	      const incident = await db.statusIncident.create({
556	        data: { component: c, severity: decision.severity, title: copy.title, body: copy.body, auto: true, startedAt: now },
557	      });
558	      await alertIncidentOpened(incident);
559	    } else if (decision.action === "resolve" && open) {
560	      await db.statusIncident.update({ where: { id: open.id }, data: { resolvedAt: now } });
561	      await alertIncidentResolved(open);
562	    }
563	  }
564	
565	  // Retention prune — best-effort, never blocks a sample.
566	  try {
567	    const cutoff = new Date(now.getTime() - HEALTH_SAMPLE_RETENTION_DAYS * 24 * 60 * 60_000);
568	    await db.healthSample.deleteMany({ where: { ts: { lt: cutoff } } });
569	  } catch (e) {
570	    console.error("[monitor] health-sample prune error", e);
571	  }
572	}
