697	export type JobStats = {
698	  windowMs: number;
699	  done: number;
700	  failed: number;
701	  /** Currently QUEUED (live depth, not windowed). */
702	  queued: number;
703	  /** Currently RUNNING (live). */
704	  running: number;
705	  /** failed / (done + failed) over the window, or `null` when nothing settled. */
706	  failureRate: number | null;
