709	/** Queue depth + settled job outcomes over the window, straight from the Job table. */
710	export async function jobStats(
711	  windowMs = 24 * 60 * 60_000,
712	  now: number = Date.now()
713	): Promise<JobStats> {
714	  const since = new Date(now - windowMs);
715	  const [done, failed, queued, running] = await Promise.all([
716	    db.job.count({ where: { status: "DONE", updatedAt: { gte: since } } }),
717	    db.job.count({ where: { status: "FAILED", updatedAt: { gte: since } } }),
718	    db.job.count({ where: { status: "QUEUED" } }),
719	    db.job.count({ where: { status: "RUNNING" } }),
720	  ]);
721	  const settled = done + failed;
722	  return { windowMs, done, failed, queued, running, failureRate: settled === 0 ? null : failed / settled };
723	}
