280	
281	/**
282	 * Is this Proxmox error specifically "vmid <n> is not on this node"?
283	 *
284	 * PVE answers a GET/DELETE for an unknown vmid with HTTP 500 and the body
285	 *   Configuration file 'nodes/<node>/qemu-server/<vmid>.conf' does not exist
286	 * (verified by running `qm config 999123` on this host, 2026-07-27).
287	 *
288	 * The match is deliberately ANCHORED ON THE VMID rather than on the bare phrase
289	 * "does not exist". `remove()` in worker/index.ts used to swallow anything whose
290	 * message contained that phrase, which also matches errors that mean the exact
291	 * opposite of "the VM is gone" — `storage 'vmdata' does not exist`, `volume ...
292	 * does not exist`, `snapshot 'x' does not exist`. Any of those would have let the
293	 * DELETE handler decide the VM had been destroyed, drop the Server row and every
294	 * Volume row pinned to it, and leave a live VM running on the hypervisor with no
295	 * database record: unbilled, unmanageable and still holding customer data.
296	 */
297	export function isVmAbsentError(e: unknown, vmid: number): boolean {
298	  const err = e as { body?: unknown; message?: unknown } | null | undefined;
299	  const msg = `${err?.body ?? ""} ${err?.message ?? (typeof e === "string" ? e : "")}`;
300	  if (!Number.isInteger(vmid)) return false;
301	  return (
302	    new RegExp(`qemu-server[/\\\\]${vmid}\\.conf'?\\s+does not exist`, "i").test(msg) ||
303	    new RegExp(`\\bVM\\s+${vmid}\\s+does not exist\\b`, "i").test(msg) ||
304	    new RegExp(`\\bno such vm\\b.*\\b${vmid}\\b`, "i").test(msg)
305	  );
306	}
