308	/**
309	 * The side-effectful half of a VM teardown, behind a seam so the decision ladder
310	 * in `destroyVmIdempotent` can be exercised without a hypervisor.
311	 * `test/vm-lifecycle.test.ts` drives it with an in-memory fake.
312	 */
313	export type VmDestroyHost = {
314	  /** Ground truth from the hypervisor. "unknown" when it could not be read — never a guess. */
315	  probe: (vmid: number) => Promise<"present" | "absent" | "unknown">;
316	  /** Best-effort stop; may reject if the VM is already stopped or gone. */
317	  stop: (vmid: number) => Promise<void>;
318	  /** The destructive call. */
319	  destroy: (vmid: number) => Promise<void>;
320	};
321	
322	export type DestroyOutcome = {
323	  /** True when THIS call issued the destroy and the VM is verified gone afterwards. */
324	  destroyed: boolean;
325	  /** True when the VM was already absent, so no destructive call was issued. */
326	  alreadyAbsent: boolean;
327	  detail: string;
328	};
