330	/**
331	 * Destroy a VM in a way that is SAFE TO RUN TWICE, and that never claims a
332	 * teardown it did not observe.
333	 *
334	 * INCIDENT (found in audit, 2026-07-27 — worker/index.ts `reinstall`): REINSTALL
335	 * is destroy-then-provision, and the worker retries a failed job up to
336	 * MAX_ATTEMPTS times. `destroyVm` issued `DELETE /qemu/<vmid>` unconditionally
337	 * and did not tolerate the VM already being gone. So when attempt 1 destroyed the
338	 * VM and then failed anywhere in the re-provision that follows (a snippet write,
339	 * a clone timeout, a config POST), attempts 2 and 3 both died on the very first
340	 * step — `Configuration file '…/<vmid>.conf' does not exist` — and never reached
341	 * the provision that was supposed to rebuild the machine. The job ended FAILED,
342	 * REINSTALL is in VM_STATE_FAILURE_JOBS so the server was flipped to ERROR, and
343	 * the customer was left with no VM at all: the retry mechanism itself converted a
344	 * recoverable mid-reinstall failure into permanent destruction. `remove()` in the
345	 * same file already tolerated the absent case, which is what made the omission
346	 * here an oversight rather than a policy.
347	 *
348	 * The ladder:
349	 *   1. PROBE FIRST. An absent VM means there is nothing to destroy — return
350	 *      without issuing any destructive call at all.
351	 *   2. "unknown" does NOT block the destroy (the caller has already decided this
352	 *      vmid is to be torn down, and the vmid is not in question), but it is
353	 *      carried into the detail so nothing downstream reads it as a clean run.
354	 *   3. TOLERATE a vmid-anchored absent error from the destroy itself — that is
355	 *      the retry racing a previous attempt that actually succeeded.
356	 *   4. VERIFY AFTER. Re-probe; if the VM is still present the destroy did not
357	 *      happen and we throw, rather than let a caller delete the database rows
358	 *      that are the only remaining handle on a live machine.
359	 */
360	export async function destroyVmIdempotent(
361	  host: VmDestroyHost,
362	  vmid: number
363	): Promise<DestroyOutcome> {
364	  const beforeState = await host.probe(vmid);
365	  if (beforeState === "absent") {
366	    return {
367	      destroyed: false,
368	      alreadyAbsent: true,
369	      detail: `VM ${vmid} was already absent — no destroy was issued`,
370	    };
371	  }
372	
373	  // Stop first. A stop failure is not fatal: the VM may already be stopped, and a
374	  // real blocker (a config lock, a running backup) will surface on the destroy.
375	  try {
376	    await host.stop(vmid);
377	  } catch {
378	    /* already stopped, or gone — the destroy below is the authority */
379	  }
380	
381	  try {
382	    await host.destroy(vmid);
383	  } catch (e) {
384	    if (!isVmAbsentError(e, vmid)) throw e;
385	    return {
386	      destroyed: false,
387	      alreadyAbsent: true,
388	      detail: `VM ${vmid} disappeared before the destroy landed — treating as already torn down`,
389	    };
390	  }
391	
392	  // Never report a teardown we did not observe.
393	  const afterState = await host.probe(vmid);
394	  if (afterState === "present") {
395	    throw new Error(
396	      `destroy of VM ${vmid} reported success but the VM is still present on the hypervisor — ` +
397	        `refusing to continue, because the caller would delete the only records that still point at it.`
398	    );
399	  }
400	  return {
401	    destroyed: true,
402	    alreadyAbsent: false,
403	    detail:
404	      afterState === "absent"
405	        ? `VM ${vmid} destroyed and verified gone`
406	        : `VM ${vmid} destroy completed, but its post-destroy state could not be read back`,
407	  };
408	}
