510	// ---------------------------------------------------------------------------
511	// In-guest disk usage via the QEMU guest agent (get-fsinfo)
512	// ---------------------------------------------------------------------------
513	
514	/** Real filesystem usage as reported from *inside* the guest. */
515	export type GuestDiskUsage = { usedBytes: number; totalBytes: number };
516	
517	/** Any client exposing `get` (satisfied by `pve` and `pveFor(...)`). */
518	export type GuestAgentClient = {
519	  get: (path: string, params?: Record<string, any>) => Promise<any>;
520	};
521	
522	// Pseudo / virtual filesystems that don't represent real on-disk usage and must
523	// never be picked as the root filesystem. Matched against the fsinfo `type`.
524	const PSEUDO_FS_TYPES = new Set([
525	  "squashfs", "tmpfs", "devtmpfs", "overlay", "overlayfs", "vfat", "msdos",
526	  "proc", "sysfs", "cgroup", "cgroup2", "debugfs", "mqueue", "hugetlbfs",
527	  "fusectl", "pstore", "autofs", "binfmt_misc", "tracefs", "configfs",
528	  "securityfs", "ramfs", "nsfs", "efivarfs", "fuse.snapfuse", "iso9660",
529	]);
530	
531	/** Is this mountpoint one we should ignore even if the type looks real? */
532	function isIgnorableMount(mountpoint: string): boolean {
533	  const mp = String(mountpoint ?? "");
534	  return (
535	    mp === "/boot" ||
536	    mp.startsWith("/boot/") ||
537	    mp.startsWith("/snap") ||
538	    mp.startsWith("/var/lib/docker") ||
539	    mp.startsWith("/run") ||
540	    mp.startsWith("/dev") ||
541	    mp.startsWith("/sys") ||
542	    mp.startsWith("/proc")
543	  );
544	}
545	
546	/**
547	 * Query the QEMU guest agent's `get-fsinfo` and return the REAL root filesystem
548	 * usage (the entry mounted at "/", excluding pseudo/boot/loop filesystems).
549	 *
550	 * Proxmox RRD's `disk` field is 0 for QEMU VMs — the hypervisor can't see
551	 * in-guest usage — so this agent call is the only source of real used/total
552	 * bytes. Best-effort: returns null on any error or when the agent isn't ready
553	 * (never throws), so a missing agent degrades cleanly to the provisioned-size
554	 * fallback. In SANDBOX returns a synthetic, gently-varying realistic value.
555	 *
556	 * @param sandboxTotalBytes only used to size the synthetic sandbox value.
557	 */
558	export async function getGuestDiskUsage(
559	  client: GuestAgentClient,
560	  node: string,
561	  vmid: number,
562	  sandboxTotalBytes?: number
563	): Promise<GuestDiskUsage | null> {
564	  if (SANDBOX) {
565	    const total = sandboxTotalBytes && sandboxTotalBytes > 0 ? sandboxTotalBytes : 40 * 1024 ** 3;
566	    const base = 0.3 + (Math.abs(vmid) % 35) / 100; // 0.30..0.64
567	    const drift = 0.03 * Math.sin(Date.now() / (6 * 3600_000) + vmid); // slow ±3%
568	    const frac = Math.min(0.95, Math.max(0.05, base + drift));
569	    return { usedBytes: Math.round(total * frac), totalBytes: total };
570	  }
571	
572	  try {
573	    const res = await client.get(`/nodes/${node}/qemu/${vmid}/agent/get-fsinfo`);
574	    // The agent wraps the array in { result: [...] }; tolerate a bare array too.
575	    const list: any[] = Array.isArray(res?.result)
576	      ? res.result
577	      : Array.isArray(res)
578	        ? res
579	        : [];
580	    if (list.length === 0) return null;
581	
582	    const real = list.filter((fs) => {
583	      const type = String(fs?.type ?? "").toLowerCase();
584	      const mp = String(fs?.mountpoint ?? "");
585	      if (PSEUDO_FS_TYPES.has(type)) return false;
586	      if (isIgnorableMount(mp)) return false;
587	      const total = Number(fs?.["total-bytes"]);
588	      return Number.isFinite(total) && total > 0;
589	    });
590	    if (real.length === 0) return null;
591	
592	    // Prefer the real root filesystem; otherwise the largest real mount.
593	    const root =
594	      real.find((fs) => String(fs?.mountpoint) === "/") ??
595	      real.sort((a, b) => Number(b?.["total-bytes"]) - Number(a?.["total-bytes"]))[0];
596	
597	    const usedBytes = Number(root?.["used-bytes"]);
598	    const totalBytes = Number(root?.["total-bytes"]);
599	    if (!Number.isFinite(usedBytes) || !Number.isFinite(totalBytes) || totalBytes <= 0) {
600	      return null;
601	    }
602	    return { usedBytes, totalBytes };
603	  } catch {
604	    // Agent not installed / not ready / VM stopped / transient PVE error.
605	    return null;
606	  }
607	}
