609	/**
610	 * Wait until the QEMU guest agent answers, i.e. until the guest has genuinely
611	 * booted far enough to run software.
612	 *
613	 * WHY: `waitForTask(startUpid)` proves only that Proxmox ACCEPTED the start —
614	 * not that the guest booted, that cloud-init ran, or that sshd is listening. The
615	 * provision path used to write RUNNING and hand the customer a copy-pasteable
616	 * `ssh root@…` line on the strength of that task alone (M7 #10), which is why a
617	 * RUNNING server eight minutes old could still show "SSH command: provisioning…".
618	 *
619	 * Returns true only on a real reply. On timeout it returns FALSE rather than
620	 * throwing, so the caller can degrade its message honestly instead of failing a
621	 * server that is merely slow — a guest with no agent installed is a normal state
622	 * for some images, and calling that a provisioning failure would be its own lie.
623	 */
624	export async function waitForGuestAgent(
625	  client: GuestAgentClient,
626	  node: string,
627	  vmid: number,
628	  timeoutMs = 180_000,
629	  pollMs = 5_000
630	): Promise<boolean> {
631	  const deadline = Date.now() + timeoutMs;
632	  for (;;) {
633	    try {
634	      await client.get(`/nodes/${node}/qemu/${vmid}/agent/ping`);
635	      return true;
636	    } catch {
637	      /* agent not up yet */
638	    }
639	    if (Date.now() >= deadline) return false;
640	    await new Promise((r) => setTimeout(r, pollMs));
641	  }
642	}
