644	/**
645	 * Force the CURRENT (DB) root password onto a running guest via the QEMU guest
646	 * agent — no reboot, no dependence on cloud-init. Same primitive `passwordReset`
647	 * (worker/index.ts) uses to change a password live; pulled out here so any other
648	 * caller whose action replaces or reverts the VM's actual disk content can reuse
649	 * it, rather than re-deriving the QGA call.
650	 *
651	 * WHY THIS EXISTS BEYOND passwordReset: `SNAPSHOT_ROLLBACK` and `BACKUP_RESTORE`
652	 * both put an OLDER copy of the guest's real disk back — including whatever
653	 * `/etc/shadow` existed at snapshot/backup time — while `Server.rootPasswordEnc`
654	 * in the DB keeps whatever the CURRENT password is. If a `PASSWORD_RESET` (or
655	 * any other password change) happened between that snapshot/backup being taken
656	 * and it being rolled back to / restored from, the guest reverts to the OLDER
657	 * password while the DB still holds the NEWER one — every later SSH from the
658	 * platform (control panel, GAME_POWER, mods, backups) then authenticates with
659	 * the DB's password against a guest that has a different one, failing with "All
660	 * configured authentication methods failed". This is the identical divergence
661	 * class documented on `provision()`'s password-reuse fix, just reached by
662	 * reverting old disk state instead of a retried clone — see that comment for the
663	 * full incident. Callers must invoke this after the VM is confirmed running and
664	 * its guest agent has answered (e.g. via `waitForGuestAgent`).
665	 *
666	 * Best-effort: never throws. Returns whether the QGA call was accepted — false
667	 * means the guest's password could not be confirmed resynced, which callers
668	 * should log loudly rather than silently swallow (the rollback/restore itself
669	 * still genuinely succeeded, so this must not fail that job).
670	 */
671	export async function applyPasswordToGuest(conn: PveClient, vmid: number, password: string): Promise<boolean> {
672	  try {
673	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/agent/set-user-password`, {
674	      username: "root",
675	      password,
676	    });
677	    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
678	    return true;
679	  } catch (e) {
680	    console.error(`[proxmox] applyPasswordToGuest failed for vmid ${vmid}`, e);
681	    return false;
682	  }
683	}
