724	// ---------------------------------------------------------------------------
725	// Platform backups vs customer backups
726	// ---------------------------------------------------------------------------
727	//
728	// DATA LOSS PREVENTED (real, on this host, 2026-07-26): `scripts/backup-vms.sh`
729	// used to write the platform's own host-level disaster-recovery archives into the
730	// SAME Proxmox storage (`backup` -> /tank/backup/dump) that customers' on-demand
731	// backups land in, and `pruneBackups` below selected victims with nothing but
732	// `b.vmid === vmid`. So vmid 102 ended the 04:31 platform run holding two
733	// archives — the customer's own manual one from 2026-07-25 12:22 and the
734	// platform's 10 GB DR copy from 2026-07-26 04:31 — and the customer's very next
735	// click on "Create backup" (keep = CUSTOMER_BACKUP_KEEP = 2) would have deleted
736	// the platform's copy of their VM. Repeated across the fleet that silently
737	// destroys the entire bare-metal recovery set, one customer click at a time.
738	//
739	// The fix is three independent layers, in order of strength:
740	//
741	//  1. STRUCTURAL. `scripts/backup-vms.sh` now writes with `vzdump --dumpdir
742	//     /tank/backup/platform`, a directory that is NOT the `dump/` subdirectory of
743	//     any configured PVE storage. Proxmox only indexes `<storage-path>/dump`, so
744	//     platform archives have no `volid` at all: they cannot appear in the
745	//     `/storage/backup/content` listing this function iterates, and there is no
746	//     volid string that `DELETE /storage/backup/content/<volid>` could resolve to
747	//     them. Not "filtered out" — not addressable.
748	//  2. CHOKEPOINT. `deleteBackup` is the only function in the repo that issues a
749	//     storage-content DELETE (whole-repo grep: this file plus its single caller in
750	//     worker/index.ts). It re-derives protection for every volid immediately
751	//     before deleting and refuses on any of: the PVE `protected` attribute, the
752	//     platform notes marker, or the protection registry — and it fails CLOSED if
753	//     it cannot determine the answer.
754	//  3. MARKER + REGISTRY. If the platform job is ever pointed back at a shared PVE
755	//     storage (`NXEON_VM_BACKUP_STORAGE=backup`), it stamps each archive with
756	//     `--notes-template` carrying PLATFORM_BACKUP_MARKER and appends the volid to
757	//     PROTECTED_REGISTRY. Both are honoured below, which also covers the archives
758	//     already sitting in /tank/backup/dump from the 2026-07-26 04:31 run, written
759	//     before layer 1 existed.
760	
761	/** Where the platform's own whole-system vzdump archives live — outside every PVE storage. */
762	export const PLATFORM_BACKUP_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";
763	
764	/**
765	 * Stamped into the vzdump notes of platform archives (see `--notes-template` in
766	 * scripts/backup-vms.sh). Customer retention must never delete an archive whose
767	 * notes contain this string.
768	 */
769	export const PLATFORM_BACKUP_MARKER = "NXEON-PLATFORM-BACKUP";
770	
771	/**
772	 * One volid per line. Maintained by scripts/backup-vms.sh; also seeded with any
773	 * pre-existing platform archives that were written into the shared storage before
774	 * the dumpdir split. Anything listed here is undeletable through this module.
775	 */
776	const PROTECTED_REGISTRY = `${PLATFORM_BACKUP_DIR}/PROTECTED-VOLIDS`;
777	
778	/**
779	 * Read the protection registry.
780	 *
781	 * Returns `null` when the registry exists but could not be read. Callers MUST
782	 * treat `null` as "protection state unknown" and refuse to delete: a transient
783	 * EIO on this file must not be the thing that lets a customer's prune wipe the
784	 * platform's recovery set. A registry that simply does not exist yet (fresh
785	 * install, platform job has never run) is a legitimate empty set — layer 1 means
786	 * there is nothing in the shared storage to protect in that case anyway.
787	 */
788	async function protectedVolids(): Promise<Set<string> | null> {
789	  const { readFile } = await import("node:fs/promises");
790	  try {
791	    const raw = await readFile(PROTECTED_REGISTRY, "utf8");
792	    return new Set(
793	      raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0 && !l.startsWith("#"))
794	    );
795	  } catch (e: any) {
796	    if (e?.code === "ENOENT") return new Set();
797	    console.error(`[proxmox] protection registry ${PROTECTED_REGISTRY} unreadable — refusing to prune`, e);
798	    return null;
799	  }
800	}
801	
802	/** Shape of one entry in `/nodes/<node>/storage/<sid>/content`. */
803	/**
804	 * Every backup archive the `backup` storage holds for one VMID, read through a
805	 * node-scoped client. This is the READ-BACK that `backupCreate` uses to prove an
806	 * archive actually exists: the vzdump task's exit status says the task ran, not
807	 * that a file landed. See worker/backup-schedule.ts (`freshBackupProof`) and
808	 * incident H4.
809	 */
810	export async function listBackupsOn(client: any, vmid: number): Promise<StorageBackupEntry[]> {
811	  const content: StorageBackupEntry[] = await client.get(
812	    `/nodes/${client.node}/storage/backup/content`,
813	    { content: "backup" }
814	  );
815	  return content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
816	}
