827	/**
828	 * Is this archive one of the platform's own (i.e. never customer-prunable)?
829	 * Any single signal is enough — they are deliberately redundant.
830	 */
831	export function isPlatformArchive(b: StorageBackupEntry, registry: Set<string>): boolean {
832	  if (b.protected) return true;
833	  if (typeof b.notes === "string" && b.notes.includes(PLATFORM_BACKUP_MARKER)) return true;
834	  if (typeof b.volid === "string" && registry.has(b.volid)) return true;
835	  return false;
836	}
