838	/**
839	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
840	 *
841	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
842	 * "a customer can never delete a platform archive" invariant is enforced rather
843	 * than merely intended. It re-checks protection against the live hypervisor for
844	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
845	 * volid cannot slip past it. Every uncertain outcome throws.
846	 */
847	export async function deleteBackup(client: any, volid: string): Promise<void> {
848	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
849	  // anything else keeps a malformed or path-traversing volid from ever reaching
850	  // the API, and keeps this function honest about what it operates on.
851	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
852	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
853	
854	  const registry = await protectedVolids();
855	  if (registry === null) {
856	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
857	  }
858	  if (registry.has(volid)) {
859	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
860	  }
861	
862	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
863	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
864	  // here means we do not know whether this is a platform archive, so we stop.
865	  let info: any;
866	  try {
867	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
868	  } catch (e) {
869	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
870	  }
871	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
872	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
873	  }
874	
875	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
876	}
877	
878	/**
879	 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
880	 * belong to that customer, deleting the older ones (best-effort per file, oldest
881	 * first). Runs after every successful customer backup, and from the standalone
882	 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
883	 *
884	 * Platform archives are excluded from the delete set AND from the retention
885	 * count. Counting them would be its own bug: with keep = 2, three platform
886	 * archives of a vmid would make every customer archive "older than the newest
887	 * two" and delete all of the customer's backups instead.
888	 */
889	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
890	  // `keep` decides how many of a customer's restore points survive, so it is
891	  // validated rather than trusted. `mine.slice(Math.max(0, keep))` looks safe and
892	  // is not: Math.max(0, NaN) is NaN, Array.slice(NaN) coerces to slice(0), and the
893	  // delete set silently becomes EVERY backup the customer has. A keep that arrived
894	  // as undefined, "" or a bad Settings parse would wipe the lot with no error on
895	  // the way past. Fail closed instead — an over-retained archive costs disk, a
896	  // missing one costs the customer their only restore point.
897	  if (!Number.isInteger(keep) || keep < 1) {
898	    throw new Error(
899	      `pruneBackups: refusing to prune vmid ${vmid} with keep='${keep}' — ` +
900	        `retention must be a whole number of at least 1.`
901	    );
902	  }
903	
904	  const registry = await protectedVolids();
905	  if (registry === null) {
906	    // Fail closed: no retention this pass. Archives accumulating for one cycle is
907	    // recoverable; deleting the platform's only copy of a VM is not.
908	    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
909	    return 0;
910	  }
911	
912	  const forVmid = await listBackupsOn(client, vmid);
913	  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
914	  const mine = forVmid
915	    .filter((b) => !isPlatformArchive(b, registry))
916	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
917	
918	  if (shielded.length > 0) {
919	    console.log(
920	      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
921	    );
922	  }
923	
924	  const toDelete = mine.slice(Math.max(0, keep));
925	  let deleted = 0;
926	  for (const b of toDelete) {
927	    try {
928	      await deleteBackup(client, b.volid!);
929	      deleted++;
930	    } catch (e) {
931	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
932	    }
933	  }
934	  return deleted;
935	}
936	
937	export async function storageStatus(storage: string): Promise<any> {
938	  return pve.get(`/nodes/${NODE}/storage/${storage}/status`);
939	}
